        for x in range(w):
            if grid[y][x] == color and (y, x) not in visited:
                comp = []
                queue = [(y, x)]
                visited.add((y, x))
                while queue:
                    cy, cx = queue.pop(0)
                    comp.append((cy, cx))
                    for dy in [-1, 0, 1]:
                        for dx in [-1, 0, 1]:
