def transform(grid):
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            color = grid[y][x]
            neighbors = []
            for dy, dx in [(-1,0), (1,0), (0,-1), (0,1)]:
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    neighbors.append(grid[ny][nx])
            if neighbors and all(n != color for n in neighbors):
                cnt = Counter(neighbors)
                majority = max(cnt.values())
                threshold = len(neighbors) / 2
                if majority > threshold:
                    result = max(e for e, c in cnt.items() if c == majority)
                else:
                    result = max(cnt.keys())
                grid[y][x] = result
    return grid
